const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const client_id = Number(input.client_id ?? 0);
const max_requests = Number(input.max_requests ?? 120);
const window_seconds = Number(input.window_seconds ?? 60);
const confirm_check = bool(input.confirm_check);

const errors = [];

if (
  !Number.isInteger(client_id) ||
  client_id < 1
) {
  errors.push({
    field: 'client_id',
    message: 'شناسه Gateway Client معتبر نیست.',
  });
}

if (
  !Number.isInteger(max_requests) ||
  max_requests < 1 ||
  max_requests > 100000
) {
  errors.push({
    field: 'max_requests',
    message: 'حداکثر تعداد درخواست معتبر نیست.',
  });
}

if (
  !Number.isInteger(window_seconds) ||
  window_seconds < 1 ||
  window_seconds > 86400
) {
  errors.push({
    field: 'window_seconds',
    message: 'بازه Rate Limit معتبر نیست.',
  });
}

if (confirm_check !== true) {
  errors.push({
    field: 'confirm_check',
    message: 'بررسی Rate Limit باید تأیید شود.',
  });
}

return [{
  json: {
    client_id,
    max_requests,
    window_seconds,
    confirm_check,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
